// Generated by tools/build_day.py from source/Day_8_NEET_SS_ICP_Paediatrics_2026_NEC_Feeding_HumanMilk_TPN_ExpertRevision_Q1_to_Q79.docx — do not edit by hand.
window.PORTAL={"day": 8, "title": "NEC + Preterm Feeding + Human Milk + TPN", "docTitle": "", "subtitle": ["DAY 8 — NEET-SS + ICP PAEDIATRICS 2026", "NEC • Preterm Feeding • Human Milk • TPN • Pediatric-Surgery Overlay"], "source": "source/Day_8_NEET_SS_ICP_Paediatrics_2026_NEC_Feeding_HumanMilk_TPN_ExpertRevision_Q1_to_Q79.docx", "pages": [{"id": "overview", "title": "Overview", "group": "Start", "kind": "overview", "sections": [{"title": "", "blocks": [{"t": "p", "html": "<strong>DAY 8 — NEET-SS + ICP PAEDIATRICS 2026</strong>"}, {"t": "p", "html": "<strong>NEC • Preterm Feeding • Human Milk • TPN • Pediatric-Surgery Overlay</strong>"}, {"t": "p", "html": "Primary conceptual reference: Nelson Textbook of Pediatrics, 22nd Edition. Guideline-sensitive nutrition and NEC content cross-checked against current AAP resources, the 2026 AAP VLBW human-milk clinical report, ESPGHAN preterm enteral-nutrition guidance, and current evidence summaries. Where exact unit protocols vary, the document labels the framework rather than presenting a local protocol as universal."}, {"t": "callout", "label": "LATEST PROTOCOL / EVIDENCE CURRENCY — OCTOBER 2026", "title": "", "html": ["Mother’s own milk (MOM), appropriately fortified, remains the preferred nutrition for hospitalized VLBW infants. If MOM is unavailable/insufficient/contraindicated, pasteurized donor human milk is recommended; the 2026 AAP clinical report supports continuing donor milk until NEC risk is low, approximately 34–36 weeks PMA. Human milk is protective against NEC; formula-fed preterm infants have higher NEC rates than human-milk-fed infants in trials, although causation by any single formula is not established. Routine universal probiotic administration remains society/region/product dependent and should not be presented as a universal AAP recommendation. NEC diagnosis remains clinical plus serial abdominal imaging; no FDA-approved biomarker establishes the diagnosis."], "fill": "EDEDED"}]}, {"title": "4-Hour Study Plan", "h1": "4-Hour Study Plan", "blocks": [{"t": "table", "head": ["<strong>Block</strong>", "<strong>Time</strong>", "<strong>Task</strong>"], "rows": [["1", "0:00–0:35", "R1/retest repair + NEC recognition framework"], ["2", "0:35–1:20", "NEC pathogenesis, Bell staging, diagnosis, treatment, surgery"], ["3", "1:20–2:00", "Preterm feeding + human milk + fortification"], ["4", "2:00–2:35", "TPN: glucose, amino acids, lipids, electrolytes, monitoring"], ["5", "2:35–3:05", "Image/tracing/data stations + pediatric-surgery discriminators"], ["6", "3:05–4:00", "Timed MCQ block; detailed Section C review is a separate post-block activity"]]}]}, {"title": "Learning Objectives", "h1": "Learning Objectives", "blocks": [{"t": "list", "ordered": false, "items": ["Recognize suspected, definite and advanced NEC and use modified Bell staging without overcalling isolated feeding intolerance.", "Explain the prematurity–dysbiosis–immature barrier–inflammation–ischemia interaction in NEC.", "Identify pneumatosis intestinalis, portal venous gas, fixed loops and pneumoperitoneum on abdominal radiographs.", "Differentiate NEC from spontaneous intestinal perforation, sepsis/ileus, malrotation-volvulus and other surgical mimics.", "Construct immediate stabilization, antibiotic, decompression, monitoring and surgical-consultation steps for NEC.", "Choose MOM, donor human milk, fortification and preterm formula rationally in VLBW infants.", "Plan initiation/advancement of enteral feeds while distinguishing physiologic residuals from red flags.", "Prescribe and monitor core neonatal PN components and recognize common PN complications.", "Apply calculations for feed volume, glucose infusion rate, energy/protein delivery and PN fluid allocation.", "Integrate current guideline-sensitive issues: donor milk, probiotics, feed advancement and post-NEC refeeding."]}]}]}, {"id": "part-1", "title": "NEC: Exam Map and Mechanism", "eyebrow": "Part I", "group": "Study Notes", "kind": "notes", "sections": [{"title": "", "blocks": [{"t": "p", "html": "NEC is an acquired inflammatory-necrotizing intestinal disease seen predominantly in preterm/VLBW infants. The exam-safe model is not a single-cause disease: immature intestinal barrier + altered microbial colonization + enteral substrate + dysregulated inflammatory signaling + impaired perfusion/oxygen delivery interact in a susceptible host."}, {"t": "callout", "label": "WHAT → WHY → HOW → RECOGNIZE → WHAT NEXT", "title": "", "html": ["Premature gut + dysbiosis/inflammatory susceptibility → mucosal injury and barrier failure → bacterial translocation, gas within bowel wall and systemic inflammation → feeding intolerance, distension, blood per rectum, metabolic acidosis/thrombocytopenia and characteristic imaging → stop feeds, decompress, stabilize, culture/antibiotics, serial examination/imaging and early surgical involvement when severe."], "fill": "EDEDED"}]}, {"title": "Modified Bell staging — practical exam version", "blocks": [{"t": "table", "head": ["<strong>Stage</strong>", "<strong>Typical clinical picture</strong>", "<strong>Imaging</strong>", "<strong>Exam consequence</strong>"], "rows": [["I — suspected", "Temperature instability, apnea/bradycardia, mild distension, emesis, occult/gross blood", "Normal or nonspecific ileus/dilation", "Do not call Stage I 'definite NEC' without pneumatosis or equivalent definite signs; reassess serially"], ["II — definite", "Persistent GI/systemic signs", "Pneumatosis ± portal venous gas; ileus", "Definite NEC; bowel rest, decompression, antibiotics, close monitoring"], ["III — advanced", "Shock, severe acidosis, DIC, peritonitis, marked abdominal signs", "Severe dilation/ascites; IIIb includes pneumoperitoneum", "PICU/NICU stabilization + urgent surgical assessment; perforation is an absolute surgical indication"]]}]}, {"title": "High-yield laboratory evolution", "blocks": [{"t": "list", "ordered": false, "items": ["Thrombocytopenia, worsening metabolic acidosis/lactate, neutropenia or neutrophilia, coagulopathy and hyponatremia can mark systemic/severe disease; none is a stand-alone diagnostic biomarker.", "Serial trends matter more than one isolated value. A rapidly falling platelet count plus worsening acidosis in an infant with abdominal signs should increase concern for progression.", "Blood cultures may be positive or negative. Obtain cultures before antibiotics when feasible without delaying treatment in an unstable infant."]}]}, {"title": "Immediate management sequence", "blocks": [{"t": "list", "ordered": true, "items": ["Stop enteral feeds (NPO) and decompress stomach with an orogastric/nasogastric tube to low intermittent/continuous suction per unit practice.", "Stabilize airway, breathing and circulation; correct shock, hypoglycemia, major electrolyte derangement and clinically important acidosis while avoiding indiscriminate bicarbonate.", "Obtain CBC/platelets, blood gas/lactate, electrolytes/glucose, coagulation profile and blood culture; trend results.", "Start broad-spectrum IV antibiotics according to local neonatal antibiogram/protocol with Gram-positive, Gram-negative and—when indicated—anaerobic coverage.", "Use serial abdominal examination and serial radiographs/ultrasound as clinically indicated; ultrasound can add bowel perfusion, wall thickness, peristalsis, free fluid and portal gas information.", "Involve pediatric surgery early for definite/severe NEC, clinical deterioration, fixed mass/erythema, worsening metabolic/hematologic markers, ascites/complex fluid, or concern for necrotic bowel; pneumoperitoneum is an absolute operative indication."]}]}, {"title": "Bell staging — full modified version (exam-critical split)", "blocks": [{"t": "table", "head": ["<strong>Stage</strong>", "<strong>Systemic signs</strong>", "<strong>Abdominal / radiographic</strong>", "<strong>Treatment</strong>"], "rows": [["IA suspected", "Temperature instability, apnea, bradycardia, lethargy", "Distension, emesis, residuals, occult blood; normal or mild ileus", "NPO, antibiotics 3 days pending cultures"], ["IB suspected", "As IA", "As IA plus bright red blood per rectum", "As IA"], ["IIA definite (mildly ill)", "As IA", "Absent bowel sounds, tenderness; pneumatosis intestinalis", "NPO, antibiotics 7-10 days"], ["IIB definite (moderately ill)", "Mild metabolic acidosis, mild thrombocytopenia", "Abdominal wall edema/tenderness ± mass; pneumatosis ± portal venous gas ± ascites", "NPO, antibiotics 14 days, bicarbonate/fluids as needed"], ["IIIA advanced (severely ill, intact bowel)", "Hypotension, bradycardia, respiratory failure, severe acidosis, DIC, neutropenia", "Peritonitis, marked tenderness and distension; ascites; no free air", "Intensive resuscitation, ventilation, inotropes; surgical review"], ["IIIB advanced (perforated)", "As IIIA", "Pneumoperitoneum", "Surgery: laparotomy or peritoneal drain"]]}]}, {"title": "NEC — antibiotics, surgery, complications, risk factors, prevention", "blocks": [{"t": "p", "html": "Antibiotics: choose according to the local neonatal antibiogram and stewardship policy. A common exam framework is ampicillin + gentamicin, with anaerobic coverage (often metronidazole) added for more advanced/surgical disease in many units; some NICUs use piperacillin-tazobactam-based regimens. No single regimen or duration is universally superior: stage, cultures, clinical response and local policy should guide therapy. Traditional Bell-based duration ranges are exam anchors, not universal mandates."}, {"t": "p", "html": "Surgical options: laparotomy with resection and enterostomy (or primary anastomosis in selected cases) versus a primary peritoneal drain, often used in ELBW or unstable infants. The NEST randomized trial found no clear difference in death or neurodevelopmental impairment between the two approaches, so choice is individualized."}, {"t": "p", "html": "Complications: intestinal stricture (the commonest late complication; usually colonic, often left-sided, presenting weeks later with obstruction or bleeding), short bowel syndrome with PN dependence, PN-associated cholestasis, stoma complications, sepsis, and neurodevelopmental impairment."}, {"t": "p", "html": "Risk factors beyond prematurity: low birth weight, formula feeding, PDA (and its treatment), umbilical venous or arterial catheters, congenital heart disease, perinatal asphyxia, polycythemia, prolonged empiric antibiotics, acid suppression (H2 blockers/PPIs), chorioamnionitis, and rapid feed advancement. Transfusion-associated NEC is debated. Term-infant NEC is usually secondary to another condition."}, {"t": "p", "html": "Prevention: antenatal corticosteroids, human milk, standardized feeding protocols, avoiding unnecessary acid suppression and prolonged antibiotics, and cautious feed advancement. Probiotics: evidence for selected strains, with recommendations varying by region and product. Lactoferrin and oropharyngeal colostrum have not been shown to be reliable NEC-preventive strategies in large trials."}, {"t": "p", "html": "Note: dosing and duration anchors in this section are typical ranges for exam orientation; verify against the unit protocol and the cited guidelines."}]}]}, {"id": "part-2", "title": "NEC Differentials & Pediatric-Surgery Overlay", "eyebrow": "Part II", "group": "Study Notes", "kind": "notes", "sections": [{"title": "", "blocks": [{"t": "table", "head": ["<strong>Entity</strong>", "<strong>Clue favoring it</strong>", "<strong>Clue against classic NEC</strong>", "<strong>Critical next step</strong>"], "rows": [["Spontaneous intestinal perforation (SIP)", "Extremely preterm; focal perforation; sudden free air; often earlier presentation", "Usually no pneumatosis/portal venous gas; less diffuse inflammatory bowel picture", "Urgent surgical consultation; stabilize"], ["Malrotation with volvulus", "Bilious vomiting, acute deterioration, obstruction; term or preterm", "Pneumatosis may be absent early; NEC risk profile not required", "Surgical emergency; do not delay definitive evaluation for serial NEC observation"], ["Hirschsprung-associated enterocolitis", "Delayed meconium/constipation, explosive stool, distension", "Different background and age pattern", "Resuscitate, decompression/irrigation + surgical team"], ["Sepsis with ileus", "Systemic infection with nonspecific bowel dilation", "No specific bowel-wall gas pattern", "Treat sepsis and reassess abdomen"], ["Milk-protein allergic proctocolitis", "Well-appearing infant, blood-streaked stool", "No systemic toxicity/pneumatosis", "Dietary evaluation; do not label a sick preterm infant with NEC red flags as allergy"]]}]}]}, {"id": "part-3", "title": "Preterm Enteral Feeding", "eyebrow": "Part III", "group": "Study Notes", "kind": "notes", "sections": [{"title": "Milk hierarchy", "blocks": [{"t": "table", "head": ["<strong>Priority</strong>", "<strong>Feed</strong>", "<strong>Why</strong>"], "rows": [["1", "Mother’s own milk (MOM)", "Preferred; bioactive and immunologic benefits; lower NEC risk; supports neurodevelopment"], ["2", "Pasteurized donor human milk (PDHM)", "Recommended when MOM unavailable/insufficient/contraindicated for VLBW; lower NEC risk than formula but often lower protein/energy after processing"], ["3", "Preterm formula", "Appropriate when human milk is unavailable or declined; nutrient dense; higher NEC risk than human milk in trials, but not proven causal"]]}, {"t": "callout", "label": "2026 AAP UPDATE — VLBW HUMAN MILK", "title": "", "html": ["The 2026 AAP clinical report states that appropriately fortified MOM is optimal for hospitalized VLBW infants. PDHM is recommended when MOM is unavailable/insufficient/contraindicated and should optimally continue until NEC risk is low, approximately 34–36 weeks PMA. Preterm formula is used when MOM is unavailable and PDHM is unavailable or declined."], "fill": "EDEDED"}]}, {"title": "Trophic feeds and advancement", "blocks": [{"t": "list", "ordered": false, "items": ["Minimal/trophic enteral nutrition exposes the gut to small milk volumes while most nutrition remains parenteral; the goal is gut maturation rather than full nutrient delivery.", "Do not use gastric residual volume alone as an automatic NEC diagnosis. Interpret color, volume, abdominal examination, stool, systemic state and trend together.", "Stable preterm infants generally benefit from early enteral feeding rather than prolonged fasting. Exact starting volumes and advancement rates vary by GA/BW, illness and unit protocol.", "Standardized feeding protocols and human-milk prioritization are associated with lower NEC risk and more consistent care.", "Feed advancement should pause when there are convincing red flags: bilious emesis/aspirate, progressive distension/tenderness/discoloration, bloody stool with illness, hemodynamic instability, significant acidosis or concerning imaging."]}]}, {"title": "Fortification", "blocks": [{"t": "p", "html": "Unfortified human milk alone often does not meet the protein, calcium, phosphorus and micronutrient needs of VLBW infants. Fortification is therefore usually required. AAP resources note that fortification to approximately 24 kcal/oz is sufficient for many VLBW infants, but individualized/targeted strategies may be used in selected units. Do not equate fortification with 'causing NEC'."}]}]}, {"id": "part-4", "title": "Human Milk: Must-Know Exam Points", "eyebrow": "Part IV", "group": "Study Notes", "kind": "notes", "sections": [{"title": "", "blocks": [{"t": "table", "head": ["<strong>Issue</strong>", "<strong>High-yield rule</strong>"], "rows": [["MOM", "First choice whenever available and safe"], ["Donor milk", "Preferred alternative for VLBW when MOM insufficient/unavailable/contraindicated"], ["Fortification", "Needed because human milk alone often underdelivers protein/minerals for VLBW growth"], ["Donor milk growth", "May support slower growth than nutrient-enriched preterm formula unless adequately fortified"], ["Probiotics", "Evidence can show NEC reduction for specific preparations, but routine universal use is not a uniform AAP recommendation; product quality and local guidance matter"], ["Human milk &amp; NEC", "Protective association; does not reduce risk to zero"]]}]}]}, {"id": "part-5", "title": "Parenteral Nutrition (TPN/PN)", "eyebrow": "Part V", "group": "Study Notes", "kind": "notes", "sections": [{"title": "", "blocks": [{"t": "p", "html": "PN bridges the nutrient gap when enteral intake is absent or insufficient. Exact neonatal PN prescriptions vary by gestation, postnatal age, fluid status, biochemical results and local formulation. For exams, know the components, calculations, monitoring and complications rather than memorizing one unit’s bag."}]}, {"title": "Core components", "blocks": [{"t": "table", "head": ["<strong>Component</strong>", "<strong>Concept</strong>", "<strong>Common exam trap</strong>"], "rows": [["Glucose", "Main carbohydrate; prescribe using GIR and monitor glucose", "Confusing mg/kg/min with g/kg/day"], ["Amino acids", "Support positive nitrogen balance/growth", "Delaying protein without indication worsens cumulative deficit"], ["Lipids", "Energy + essential fatty acids", "Ignoring triglycerides, sepsis/critical illness context or line compatibility"], ["Electrolytes", "Na/K/Ca/P/Mg individualized to age, renal function and labs", "Adding potassium before confirming urine output/renal status"], ["Vitamins/trace elements", "Needed in prolonged PN", "Forgetting cholestasis-related trace-element adjustments"], ["Fluid", "Total fluid must include PN + lipids + drugs + flushes + enteral feeds", "Double-counting or ignoring medication volumes"]]}]}, {"title": "PN complications", "blocks": [{"t": "list", "ordered": false, "items": ["Catheter-related bloodstream infection/thrombosis", "Hyperglycemia or hypoglycemia during abrupt changes", "Hypertriglyceridemia", "Electrolyte/mineral disturbances and metabolic bone disease risk", "PN-associated cholestasis/intestinal failure–associated liver disease", "Refeeding-type electrolyte shifts in severely growth-restricted infants if nutrition is advanced without monitoring"]}]}]}, {"id": "part-6", "title": "India / NNF Overlay — Exam-Relevant Differences", "eyebrow": "", "group": "Study Notes", "kind": "notes", "sections": [{"title": "", "blocks": [{"t": "p", "html": "Use this as a labelled India-specific overlay rather than replacing AAP/ESPGHAN guidance. NNF India maintains dedicated guidance for breastmilk in preterm infants and feeding of low-birth-weight neonates. NNF strongly recommends routine Kangaroo Mother Care (KMC) for LBW infants and supports multinutrient human-milk fortification."}, {"t": "p", "html": "Probiotics illustrate guideline-context differences: NNF LBW-feeding guidance supports selected multistrain probiotics in stable LBW infants when enteral feeds begin, whereas AAP guidance is more cautious about routine universal use because benefits and safety depend on strain/product quality and regulation. In an exam stem, follow the society/framework named."}, {"t": "p", "html": "KMC/skin-to-skin care supports thermoregulation, lactation and comprehensive preterm/LBW care. Human-milk-bank access varies across Indian centres; when MOM is insufficient, screened pasteurized donor milk is preferred where available."}]}, {"title": "EVIDENCE-GRADING CAUTION FOR NEC RISK FACTORS", "blocks": [{"t": "p", "html": "Commonly tested associations include prematurity/VLBW, lower human-milk exposure, prolonged empiric antibiotics and acid suppression. Congenital heart disease/systemic hypoperfusion is important in term NEC. PDA therapies, umbilical catheters and transfusion-associated NEC are better treated as context-dependent associations/controversies rather than simple proven causal factors."}]}]}, {"id": "numbers", "title": "Must-Know Numbers", "group": "Quick Reference", "kind": "notes", "sections": [{"title": "", "blocks": [{"t": "table", "head": ["<strong>Item</strong>", "<strong>Formula / exam-safe anchor</strong>"], "rows": [["Feed volume", "mL/kg/day × weight (kg) = total mL/day"], ["Per-feed volume", "total mL/day ÷ number of feeds/day"], ["GIR", "glucose concentration (mg/mL) × mL/kg/day ÷ 1440 = mg/kg/min"], ["Dextrose concentration", "D10 = 100 mg/mL; D12.5 = 125 mg/mL"], ["Energy from carbohydrate", "~3.4 kcal/g dextrose"], ["Energy from amino acids", "~4 kcal/g"], ["Energy from IV lipid", "~10 kcal/g (product-dependent formulation details can vary)"], ["Full enteral volume", "Often around 150–160 mL/kg/day in practice, individualized"], ["AAP donor milk continuation", "Approximately 34–36 weeks PMA while NEC risk remains high"]]}, {"t": "callout", "label": "EXAM CAUTION", "title": "", "html": ["Feeding-start volumes, advancement rates, fortification thresholds, antibiotic combinations/durations and exact PN macronutrient targets vary by neonatal unit and patient phenotype. When a stem supplies a protocol, calculate within that protocol. When it does not, choose the physiologically safe principle and current guideline direction rather than inventing a universal number."], "fill": "EDEDED"}]}, {"title": "Typical anchor ranges (exam orientation; unit protocols vary)", "blocks": [{"t": "table", "head": ["<strong>Item</strong>", "<strong>Typical range</strong>"], "rows": [["Trophic feeds", "About 10-20 mL/kg/day, started early in stable preterm infants"], ["Feed advancement", "About 20-30 mL/kg/day (ESPGHAN range 15-30), slower in ELBW or ill infants"], ["Fortification", "Begin around 80-100 mL/kg/day of feeds; commonly to about 24 kcal/oz; adjust to growth and BUN"], ["Full enteral target", "About 150-180 mL/kg/day; energy about 110-135 kcal/kg/day; protein about 3.5-4.5 g/kg/day"], ["PN amino acids", "Start early (about 1.5-3 g/kg/day), advance to about 3.5-4 g/kg/day"], ["PN lipid", "Start about 1-2 g/kg/day, advance to about 3-4 g/kg/day; reduce with high triglycerides or sepsis"], ["GIR", "Start about 4-6 mg/kg/min (higher in some term/near-term infants); usual ceiling about 12 mg/kg/min"], ["PN cholestasis", "Direct bilirubin above 1 mg/dL; mitigate with enteral feeds, line care, lipid optimization (including fish-oil-containing emulsions)"], ["Bone/minerals", "Calcium and phosphate adequate, vitamin D about 400 IU/day (some guidelines 800-1000 IU), monitor ALP; iron about 2-4 mg/kg/day from 2-6 weeks"]]}]}]}, {"id": "tables", "title": "Tables & Algorithms", "group": "Quick Reference", "kind": "notes", "sections": [{"title": "Algorithm 1 — Suspected NEC", "h1": "Part VII — Algorithms", "blocks": [{"t": "list", "ordered": true, "items": ["Recognize systemic + abdominal red flags", "NPO + gastric decompression", "Stabilize ABC/perfusion/glucose", "CBC/platelets + gas/lactate + electrolytes + culture", "Abdominal radiograph ± ultrasound", "Start protocol-appropriate IV antibiotics", "Serial examination/labs/imaging", "Escalate early to pediatric surgery if progression/definite severe disease"]}]}, {"title": "Algorithm 2 — Preterm feeding", "h1": "", "blocks": [{"t": "list", "ordered": true, "items": ["Assess stability and contraindications/red flags", "Prioritize MOM", "Use PDHM when MOM inadequate/unavailable/contraindicated", "Start small enteral feeds when medically feasible", "Advance using standardized protocol and clinical tolerance", "Fortify to meet preterm nutrient needs", "Track weight, length, head circumference and biochemical nutrition markers", "Reduce PN as safe enteral nutrient delivery rises"]}]}, {"title": "Algorithm 3 — Bilious vomiting in a neonate", "h1": "", "blocks": [{"t": "list", "ordered": true, "items": ["Treat bilious emesis as intestinal obstruction until proven otherwise", "Stabilize and decompress", "Do not assume 'feeding intolerance'", "Urgent surgical assessment and appropriate imaging", "Differentiate volvulus/obstruction from NEC using history, exam and imaging", "If volvulus suspected, time-critical surgical management takes priority"]}]}]}, {"id": "cases", "title": "Clinical Cases", "group": "Practice", "kind": "cases", "sections": [{"title": "Case 1 — Definite NEC", "blocks": [{"t": "p", "html": "Stem: 29-week infant, day 12, abdominal distension, blood in stool, apnea; platelets falling; radiograph shows pneumatosis."}, {"t": "p", "html": "Structured reasoning: Definite NEC (Bell II or higher depending full severity). NPO, decompress, stabilize, cultures/antibiotics, serial monitoring. Falling platelets increase concern for progression."}, {"t": "p", "html": "Closest distractor: Isolated feeding intolerance or sepsis ileus."}, {"t": "p", "html": "Exam trap: Calling this isolated feeding intolerance because the baby is only on day 12 of feeds."}]}, {"title": "Case 2 — SIP discriminator", "blocks": [{"t": "p", "html": "Stem: 24-week ELBW infant has sudden abdominal discoloration and free air. No prior pneumatosis/portal gas."}, {"t": "p", "html": "Structured reasoning: SIP is an important close differential. Stabilize and obtain urgent surgical input; the absence of classic NEC bowel-wall findings favors SIP but does not make the emergency less urgent."}, {"t": "p", "html": "Closest distractor: NEC with perforation (but no pneumatosis/portal gas)."}, {"t": "p", "html": "Exam trap: Assuming free air equals NEC and delaying surgical input while debating the label."}]}, {"title": "Case 3 — Volvulus trap", "blocks": [{"t": "p", "html": "Stem: Term neonate with sudden bilious vomiting and progressive abdominal pain, no pneumatosis."}, {"t": "p", "html": "Structured reasoning: Malrotation with volvulus must be treated as a surgical emergency. Bilious vomiting is not routine feeding intolerance."}, {"t": "p", "html": "Closest distractor: NEC (but there is no pneumatosis and the vomiting is bilious)."}, {"t": "p", "html": "Exam trap: Waiting for serial NEC films while bilious vomiting persists."}]}, {"title": "Case 4 — Human milk choice", "blocks": [{"t": "p", "html": "Stem: VLBW infant; MOM supply currently insufficient."}, {"t": "p", "html": "Structured reasoning: Use MOM first; supplement with PDHM when available. Fortify human milk to meet preterm nutrient needs. Do not delay nutrition waiting indefinitely for full MOM volume."}, {"t": "p", "html": "Closest distractor: Formula (only if donor milk is unavailable or declined)."}, {"t": "p", "html": "Exam trap: Waiting for full maternal volume before feeding, or skipping fortification."}]}, {"title": "Case 5 — Residual trap", "blocks": [{"t": "p", "html": "Stem: Stable 31-week infant has a small nonbilious gastric residual but soft abdomen, normal stool and stable vitals."}, {"t": "p", "html": "Structured reasoning: Do not diagnose NEC from residual volume alone. Assess the whole clinical pattern and standardized feeding protocol."}, {"t": "p", "html": "Closest distractor: NEC from the residual alone."}, {"t": "p", "html": "Exam trap: Labelling NEC from one nonbilious residual in a well infant."}]}, {"title": "Case 6 — PN hyperglycemia", "blocks": [{"t": "p", "html": "Stem: ELBW infant on PN has persistent hyperglycemia after GIR increase."}, {"t": "p", "html": "Structured reasoning: Confirm sampling, calculate actual GIR including all glucose-containing infusions, reduce excessive GIR if appropriate and address stress/sepsis/drugs; insulin is not the reflex first answer for every case."}, {"t": "p", "html": "Closest distractor: Starting insulin first."}, {"t": "p", "html": "Exam trap: Reflexive insulin before auditing GIR from all glucose sources."}]}, {"title": "Case 7 — Cholestasis", "blocks": [{"t": "p", "html": "Stem: Preterm infant has prolonged PN exposure and rising direct bilirubin."}, {"t": "p", "html": "Structured reasoning: Consider PN/intestinal-failure associated cholestasis; maximize safe enteral nutrition, review infection and other cholestasis causes, and optimize PN rather than attributing every direct bilirubin rise to PN without evaluation."}, {"t": "p", "html": "Closest distractor: Attributing all cholestasis to PN without work-up."}, {"t": "p", "html": "Exam trap: Missing sepsis, biliary atresia and metabolic causes of conjugated hyperbilirubinemia."}]}, {"title": "Case 8 — Post-NEC refeeding", "blocks": [{"t": "p", "html": "Stem: Infant with medically treated NEC is clinically well and imaging/labs have normalized."}, {"t": "p", "html": "Structured reasoning: Prolonged arbitrary fasting is not evidence-based. Refeeding timing is individualized; emerging protocols support earlier cautious human-milk reintroduction after clinical/radiographic resolution rather than automatically waiting a fixed long duration."}, {"t": "p", "html": "Closest distractor: Prolonged arbitrary fasting versus reflexive full-volume refeeding."}, {"t": "p", "html": "Exam trap: Fasting for a fixed 14 days regardless of recovery."}]}]}, {"id": "data", "title": "Data Interpretation", "group": "Practice", "kind": "data", "sections": [{"title": "", "blocks": [{"t": "p", "html": "All images below are purpose-built radiograph-style educational schematics, not patient radiographs. They reproduce the key spatial patterns more faithfully than simple cartoons, but real neonatal films remain noisier and require systematic interpretation."}]}, {"title": "Visual Station 1 — Pneumatosis intestinalis", "blocks": [{"t": "img", "src": "img/gen_pneumatosis.png", "alt": "", "caption": "Generated radiograph-style teaching schematic — not a patient image."}, {"t": "img", "src": "img/image7.png", "alt": "", "reveal": true, "caption": "Labelled schematic from the source document"}, {"t": "p", "html": "Question: A preterm infant develops distension and blood-streaked stool. What does the highlighted bowel-wall pattern represent?"}, {"t": "p", "html": "Interpretation: Pneumatosis intestinalis — gas within the bowel wall; in the correct clinical context it supports definite NEC."}, {"t": "p", "html": "Decisive visual/data features: Mottled stool/fecal material is intraluminal; pneumatosis tracks the bowel wall in linear/bubbly lucencies."}, {"t": "p", "html": "Closest distractor / discriminator: Intraluminal stool mottling/fecal material."}, {"t": "p", "html": "Next management step: Make the infant NPO, decompress, stabilize, culture/start antibiotics and use serial imaging/examination."}, {"t": "p", "html": "Exam trap: Do not dismiss pneumatosis as simple 'feed intolerance'."}, {"t": "p", "html": "Trace-back: Day 8 — NEC / feeding / PN."}]}, {"title": "Visual Station 2 — Portal venous gas", "blocks": [{"t": "img", "src": "img/gen_portal_gas.png", "alt": "", "caption": "Generated radiograph-style teaching schematic — not a patient image."}, {"t": "img", "src": "img/image8.png", "alt": "", "reveal": true, "caption": "Labelled schematic from the source document"}, {"t": "p", "html": "Question: What is the branching lucency projected over the hepatic region?"}, {"t": "p", "html": "Interpretation: Portal venous gas, an important radiographic/ultrasound finding that can accompany NEC."}, {"t": "p", "html": "Decisive visual/data features: Portal venous gas extends into small peripheral portal radicals; pneumobilia is more central near the hilum."}, {"t": "p", "html": "Closest distractor / discriminator: Pneumobilia (central, near the hilum)."}, {"t": "p", "html": "Next management step: Treat as definite/significant NEC in the clinical context and assess severity/progression."}, {"t": "p", "html": "Exam trap: Portal venous gas is not the same as free intraperitoneal air."}, {"t": "p", "html": "Trace-back: Day 8 — NEC / feeding / PN."}]}, {"title": "Visual Station 3 — Pneumoperitoneum", "blocks": [{"t": "img", "src": "img/gen_free_air.png", "alt": "", "caption": "Generated radiograph-style teaching schematic — not a patient image."}, {"t": "img", "src": "img/image9.png", "alt": "", "reveal": true, "caption": "Labelled schematic from the source document"}, {"t": "p", "html": "Question: What management-changing finding is shown?"}, {"t": "p", "html": "Interpretation: Free intraperitoneal air from bowel perforation."}, {"t": "p", "html": "Decisive visual/data features: Free air lies outside bowel loops and may form a subdiaphragmatic crescent or football-type collection depending on projection."}, {"t": "p", "html": "Closest distractor / discriminator: Skin-fold or overlying artefact versus true free air; also gas within a dilated loop."}, {"t": "p", "html": "Next management step: Urgent pediatric-surgical management after immediate stabilization; perforation is an absolute surgical indication."}, {"t": "p", "html": "Exam trap: Do not wait for worsening laboratory markers once perforation is demonstrated."}, {"t": "p", "html": "Trace-back: Day 8 — NEC / feeding / PN."}]}, {"title": "Visual Station 4 — Fixed/persistent dilated loop", "blocks": [{"t": "img", "src": "img/gen_fixed_loop.png", "alt": "", "caption": "Generated radiograph-style teaching schematic — not a patient image."}, {"t": "img", "src": "img/image10.png", "alt": "", "reveal": true, "caption": "Labelled schematic from the source document"}, {"t": "p", "html": "Question: Why is a bowel loop that remains dilated in the same location on serial films concerning?"}, {"t": "p", "html": "Interpretation: A persistent/fixed dilated loop can suggest localized severely diseased/necrotic bowel, especially with other NEC progression signs."}, {"t": "p", "html": "Decisive visual/data features: Persistence of the same focally dilated loop on serial films, especially with clinical/laboratory deterioration, is more concerning than transient generalized ileus."}, {"t": "p", "html": "Closest distractor / discriminator: Transient generalized gaseous ileus."}, {"t": "p", "html": "Next management step: Escalate surveillance and surgical discussion rather than relying on one isolated film."}, {"t": "p", "html": "Exam trap: A fixed loop is concerning but is not by itself equivalent to pneumoperitoneum."}, {"t": "p", "html": "Trace-back: Day 8 — NEC / feeding / PN."}]}, {"title": "Visual Station 5 — NEC vs SIP", "blocks": [{"t": "img", "src": "img/gen_free_air.png", "alt": "", "caption": "Generated radiograph-style teaching schematic — not a patient image."}, {"t": "img", "src": "img/image11.png", "alt": "", "reveal": true, "caption": "Labelled schematic from the source document"}, {"t": "p", "html": "Question: An ELBW infant has sudden pneumoperitoneum but no pneumatosis or portal venous gas. Which close mimic becomes more likely?"}, {"t": "p", "html": "Interpretation: Spontaneous intestinal perforation (SIP), particularly with an isolated focal perforation phenotype."}, {"t": "p", "html": "Decisive visual/data features: NEC more often shows diffuse inflammatory bowel disease with pneumatosis/portal gas; SIP often presents as isolated perforation/free air without those classic findings."}, {"t": "p", "html": "Closest distractor / discriminator: NEC with perforation (diffuse bowel-wall gas) rather than an isolated perforation."}, {"t": "p", "html": "Next management step: Stabilize and involve pediatric surgery urgently; do not delay because the label is uncertain."}, {"t": "p", "html": "Exam trap: Free air does not automatically mean NEC."}, {"t": "p", "html": "Trace-back: Day 8 — NEC / feeding / PN."}]}, {"title": "Visual Station 6 — Feeding/PN transition data", "blocks": [{"t": "img", "src": "img/image12_q.png", "alt": ""}, {"t": "img", "src": "img/image12.png", "alt": "", "reveal": true, "caption": "Labelled schematic from the source document"}, {"t": "p", "html": "Question: What principle does the crossing trajectory illustrate?"}, {"t": "p", "html": "Interpretation: As tolerated enteral nutrient delivery rises, PN/IV contribution can be reduced while maintaining total fluid/nutrient goals."}, {"t": "p", "html": "Decisive visual/data features: The decision is driven by clinical tolerance and nutrient delivery, not a cosmetic target line."}, {"t": "p", "html": "Closest distractor / discriminator: Fixing a 'target line' for PN rather than recalculating nutrient delivery."}, {"t": "p", "html": "Next management step: Recalculate total fluids, GIR, protein/energy and electrolytes whenever feed or PN volume changes."}, {"t": "p", "html": "Exam trap: Never reduce PN without checking whether enteral feeds actually replace glucose/protein/mineral delivery."}, {"t": "p", "html": "Trace-back: Day 8 — NEC / feeding / PN."}]}]}, {"id": "quizzes", "title": "Quizzes", "group": "Practice", "kind": "quizzes", "sections": []}, {"id": "revision", "title": "Rapid Revision", "group": "Revise", "kind": "revision", "sections": [{"title": "", "blocks": [{"t": "list", "ordered": false, "items": ["NEC = susceptible premature gut + dysbiosis/inflammation + enteral substrate + perfusion vulnerability.", "Pneumatosis = bowel-wall gas; portal venous gas supports significant disease; pneumoperitoneum = perforation and urgent surgery.", "SIP: focal perforation/free air, often ELBW, usually no pneumatosis/portal gas.", "Bilious vomiting = obstruction/volvulus until proven otherwise.", "MOM first; PDHM next for VLBW when MOM insufficient; fortify human milk for preterm nutrient needs.", "2026 AAP: PDHM can optimally continue until NEC risk is low, ~34–36 weeks PMA.", "Do not diagnose NEC from gastric residual alone.", "PN calculations: total fluid, GIR, amino acids, lipids, electrolytes; recalculate when feeds change.", "Routine universal probiotic use is not a single global rule—know society/product context.", "Perforation is absolute surgical indication; deterioration without free air can still require surgery."]}]}]}, {"id": "recall", "title": "Active Recall", "group": "Revise", "kind": "recall", "sections": [{"title": "", "blocks": [{"t": "list", "ordered": true, "items": ["Define the classic radiographic sign of definite NEC.<br>Answer: Pneumatosis intestinalis: gas within the bowel wall.", "List three systemic markers suggesting NEC progression.<br>Answer: Examples: falling platelets, worsening metabolic acidosis/lactate, shock, neutropenia/coagulopathy/hyponatremia depending case.", "State the immediate first six actions for suspected NEC.<br>Answer: NPO; gastric decompression; ABC/perfusion stabilization; labs/culture; abdominal imaging; IV antibiotics; then serial monitoring/early surgery as severity dictates.", "Differentiate pneumatosis from portal venous gas.<br>Answer: Pneumatosis is intramural bowel-wall gas; portal venous gas is branching gas in portal venous structures, often peripheral in liver.", "What finding is an absolute surgical indication?<br>Answer: Pneumoperitoneum from perforation.", "Give two clues favoring SIP over NEC.<br>Answer: Isolated focal perforation/free air; absence of pneumatosis/portal gas and less diffuse inflammatory bowel picture.", "What does bilious vomiting mean until proven otherwise?<br>Answer: Possible intestinal obstruction/malrotation-volvulus requiring urgent evaluation.", "State the milk hierarchy for VLBW infants.<br>Answer: MOM → PDHM if MOM unavailable/insufficient/contraindicated → preterm formula when human milk unavailable/declined.", "Why does human milk require fortification in VLBW infants?<br>Answer: Protein, calcium, phosphorus and other nutrient delivery from unfortified milk may not meet VLBW requirements.", "What is the 2026 AAP approximate PMA range for continuing PDHM while NEC risk remains high?<br>Answer: Approximately 34–36 weeks PMA.", "Why is gastric residual volume alone insufficient to diagnose NEC?<br>Answer: Residuals are nonspecific; use systemic state, abdomen, stool and imaging/trends.", "Give four red flags that should pause feed advancement.<br>Answer: Bilious emesis, progressive distension/tenderness/discoloration, bloody stool with illness, instability/acidosis/concerning imaging.", "What is GIR and its unit?<br>Answer: Glucose infusion rate; mg/kg/min.", "How much glucose is in D10 in mg/mL?<br>Answer: 100 mg/mL.", "Write the GIR formula using concentration and mL/kg/day.<br>Answer: GIR = glucose concentration (mg/mL) × mL/kg/day ÷ 1440.", "List five PN complications.<br>Answer: Line infection/thrombosis, glucose disturbance, hypertriglyceridemia, electrolyte/mineral problems, cholestasis, refeeding-type shifts.", "What should be checked before substantial potassium is added to PN?<br>Answer: Urine output, renal function and serum potassium/overall electrolyte status.", "Why should PN be recalculated when enteral feeds advance?<br>Answer: To preserve total fluid, GIR, protein/energy and electrolytes while avoiding over- or under-delivery.", "Differentiate NEC from allergic proctocolitis.<br>Answer: Allergic proctocolitis often occurs in a well infant with isolated blood-streaking and no systemic toxicity/pneumatosis; NEC is systemic/inflammatory with pathologic abdominal findings.", "What can abdominal ultrasound add in NEC?<br>Answer: Bowel perfusion, wall thickness, peristalsis, portal gas and free/complex fluid; it complements radiographs.", "Visual: what does bowel-wall bubbly/linear lucency represent?<br>Answer: Pneumatosis intestinalis.", "Visual: what does branching peripheral hepatic lucency represent?<br>Answer: Portal venous gas.", "Visual: what does free intraperitoneal air change in management?<br>Answer: Urgent surgical management after stabilization; perforation is an absolute operative indication.", "Visual: what is the significance of a persistent fixed loop?<br>Answer: Concern for focal severe/necrotic bowel when persistent on serial films; it is concerning but not alone equivalent to perforation.", "State the DOPE, Jensen-BPD and G6PD error-notebook corrections due today.<br>Answer: Circuit disconnection = Equipment failure; invasive ventilation at 36 weeks PMA = Jensen Grade 3 BPD; G6PD severe unconjugated jaundice may be DAT-negative."]}]}]}, {"id": "notebook", "title": "Error Notebook", "group": "Revise", "kind": "notebook", "sections": []}, {"id": "plan", "title": "Revision Plan", "group": "Revise", "kind": "plan", "sections": [{"title": "Beginning-Of-Day Error Notebook Repair", "h1": "Beginning-Of-Day Error Notebook Repair", "blocks": [{"t": "table", "head": ["<strong>Concept</strong>", "<strong>Source</strong>", "<strong>Type</strong>", "<strong>Failure count</strong>", "<strong>Status</strong>", "<strong>Today’s action</strong>"], "rows": [["DOPE: explicit circuit disconnection = equipment failure", "Day 5 Q34", "S", "1×", "AMBER", "Fresh extra retest at Q16; outside base 75"], ["Jensen BPD severity at 36 weeks PMA: invasive mechanical ventilation = Grade 3", "Day 5 Q53", "K", "1×", "AMBER", "Fresh extra retest at Q55; outside base 75"], ["G6PD severe unconjugated jaundice can be DAT-negative", "Day 6 Q60", "K", "1×", "AMBER", "Fresh extra retest at Q71; outside base 75"], ["Jensen Grade 3 BPD at 36 weeks PMA = invasive mechanical ventilation", "Day 5 Q4", "K", "1×", "AMBER", "Fresh extra retest at Q35; outside base 75"]]}, {"t": "callout", "label": "R1 QUICK RECALL — ANSWERS HIDDEN BELOW", "title": "", "html": ["1. In a ventilated neonate with sudden deterioration and an explicitly disconnected circuit, which DOPE category is primary?<br>2. At 36 weeks PMA, an infant requiring invasive mechanical ventilation falls into which Jensen BPD grade?<br>3. Can G6PD-related severe unconjugated hyperbilirubinemia be DAT-negative?<br>4. Day 5 Q4 concept: what respiratory support defines Jensen Grade 3 BPD at 36 weeks PMA?"], "fill": "EDEDED"}, {"t": "callout", "label": "R1 QUICK RECALL — ANSWERS", "title": "", "html": ["1. E — Equipment failure. 2. Grade 3 BPD. 3. Yes; DAT negativity does not exclude nonimmune hemolysis such as G6PD deficiency. 4. Invasive mechanical ventilation."], "fill": "EDEDED"}]}, {"title": "Self-Assessment & Performance Tracking", "h1": "Self-Assessment & Performance Tracking", "blocks": [{"t": "table", "head": ["<strong>Domain</strong>", "<strong>Record</strong>"], "rows": [["Base MCQs", "__/75"], ["Accuracy", "__%"], ["Guessed-correct", "__"], ["K/C/R/G/S", "K__ C__ R__ G__ S__"], ["Visual/data MCQs", "__/__"], ["Close-distractor accuracy", "__/__"], ["Calculation Drill", "__/8"], ["RED / AMBER / GREEN", "R__ / A__ / G__"], ["Repeated failures x2+", "__"], ["Notebook Retests — Extra", "__/4 (Q16, Q35, Q55, Q71; outside base-75 score)"], ["Total questions attempted", "__/79"]]}, {"t": "p", "html": "R1: ~24 h • R2: ~7 d • R3: ~21 d. Guessed-correct and uncertain answers remain AMBER until demonstrated by separated successful retrievals."}]}]}, {"id": "references", "title": "References", "group": "More", "kind": "notes", "sections": [{"title": "References & Guideline Anchors", "h1": "References & Guideline Anchors", "blocks": [{"t": "p", "html": "National Neonatology Forum India (NNF). Clinical Practice Guidelines: Breastmilk for preterm neonates; Feeding of low-birth-weight neonates. India-specific overlay used for KMC, feeding, fortification and probiotic context."}, {"t": "p", "html": "NNF / MoHFW India resources: Kangaroo Mother Care and optimal feeding of LBW infants."}, {"t": "list", "ordered": false, "items": ["Nelson Textbook of Pediatrics, 22nd Edition — primary conceptual reference.", "American Academy of Pediatrics. Necrotizing Enterocolitis (NEC), updated July 17, 2024.", "American Academy of Pediatrics. Promoting Human Milk and Breastfeeding for the Very Low Birth Weight Infant. Pediatrics. 2026;157(2):e2025073625.", "ESPGHAN Committee on Nutrition. Enteral Nutrition in Preterm Infants: 2022 Position Paper.", "American Academy of Pediatrics. Nutrition for VLBW Infants and Newborns, updated February 13, 2026.", "Current evidence on early/progressive enteral feeding and NEC was used to avoid presenting prolonged fasting or one advancement rate as a universal rule."]}]}]}], "quizSets": [{"k": 1, "from": 1, "to": 16, "n": 16}, {"k": 2, "from": 17, "to": 32, "n": 16}, {"k": 3, "from": 33, "to": 48, "n": 16}, {"k": 4, "from": 49, "to": 64, "n": 16}, {"k": 5, "from": 65, "to": 79, "n": 15}], "mcqCount": 79, "planLinks": [["plan", "part-1"], ["part-1", "part-2"], ["part-3", "part-4"], ["part-5"], ["data", "part-2"], ["quizzes"]], "calc": {"n": 8, "href": "calc.html"}};
